     2	
     3	import com.fasterxml.jackson.databind.ObjectMapper;
     4	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
     5	import com.shop.dto.CheckoutSummary;
     6	import com.shop.model.OrderItem;
     7	import com.shop.model.enums.*;
     8	import org.postgresql.util.PGobject;
     9	
    10	import java.math.BigDecimal;
    11	import java.sql.*;
    12	import java.util.ArrayList;
    13	import java.util.List;
    14	
    15	public class Database {
    16	    private static final ObjectMapper objectMapper = new ObjectMapper()
    17	            .registerModule(new JavaTimeModule());
    18	
    19	    private final String url;
    20	    private final String user;
    21	    private final String password;
    22	
    23	    public Database(String url, String user, String password) {
    24	        this.url = url;
    25	        this.user = user;
    26	        this.password = password;
    27	    }
    28	
    29	    public Connection getConnection() throws SQLException {
    30	        return DriverManager.getConnection(url, user, password);
    31	    }
    32	
    33	    public void initialize() {
    34	        try (Connection conn = getConnection()) {
    35	            createTables(conn);
    36	            loadInitialCatalog(conn);
    37	        } catch (SQLException e) {
    38	            throw new RuntimeException("Failed to initialize database", e);
    39	        }
    40	    }
    41	
    42	    private void createTables(Connection conn) throws SQLException {
    43	        String[] sqls = {
    44	            """
    45	            CREATE TABLE IF NOT EXISTS products (
    46	                sku VARCHAR(50) PRIMARY KEY,
    47	                name VARCHAR(200) NOT NULL,
    48	                price DECIMAL(10,2) NOT NULL,
    49	                weight_kg DECIMAL(10,3) NOT NULL,
    50	                stock INTEGER NOT NULL,
    51	                discontinued BOOLEAN NOT NULL DEFAULT FALSE
    52	            )
    53	            """,
    54	            """
    55	            CREATE TABLE IF NOT EXISTS customers (
    56	                cpf VARCHAR(11) PRIMARY KEY,
    57	                email VARCHAR(255) NOT NULL,
    58	                credit_balance DECIMAL(10,2) NOT NULL DEFAULT 0
    59	            )
    60	            """,
    61	            """
    62	            CREATE TABLE IF NOT EXISTS orders (
    63	                id BIGSERIAL PRIMARY KEY,
    64	                customer_cpf VARCHAR(11) NOT NULL,
    65	                status VARCHAR(50) NOT NULL,
    66	                created_at TIMESTAMP NOT NULL,
    67	                summary JSONB NOT NULL,
    68	                items JSONB NOT NULL,
    69	                tracking_code VARCHAR(100),
    70	                last_payment_transaction_id VARCHAR(100),
    71	                FOREIGN KEY (customer_cpf) REFERENCES customers(cpf)
    72	            )
    73	            """,
    74	            """
    75	            CREATE TABLE IF NOT EXISTS notifications (
    76	                id BIGSERIAL PRIMARY KEY,
    77	                type VARCHAR(50) NOT NULL,
    78	                order_id BIGINT NOT NULL,
    79	                customer_cpf VARCHAR(11) NOT NULL,
    80	                status VARCHAR(50) NOT NULL,
    81	                FOREIGN KEY (order_id) REFERENCES orders(id),
    82	                FOREIGN KEY (customer_cpf) REFERENCES customers(cpf)
    83	            )
    84	            """,
    85	            """
    86	            CREATE INDEX IF NOT EXISTS idx_orders_customer ON orders(customer_cpf)
    87	            """,
    88	            """
    89	            CREATE INDEX IF NOT EXISTS idx_notifications_customer ON notifications(customer_cpf)
    90	            """
    91	        };
    92	
    93	        for (String sql : sqls) {
    94	            try (Statement stmt = conn.createStatement()) {
    95	                stmt.execute(sql);
    96	            }
    97	        }
    98	    }
    99	
   100	    private void loadInitialCatalog(Connection conn) throws SQLException {
   101	        String checkSql = "SELECT COUNT(*) FROM products";
   102	        try (Statement stmt = conn.createStatement();
   103	             ResultSet rs = stmt.executeQuery(checkSql)) {
   104	            if (rs.next() && rs.getInt(1) > 0) {
   105	                return;
   106	            }
   107	        }
   108	
   109	        String insertSql = """
   110	            INSERT INTO products (sku, name, price, weight_kg, stock, discontinued) VALUES
   111	            ('CAM-001', 'Camiseta básica', 79.90, 0.30, 50, false),
   112	            ('TEN-001', 'Tênis corrida', 249.90, 1.20, 10, false),
   113	            ('FON-001', 'Fone sem fio', 199.90, 0.25, 5, false),
   114	            ('MEI-001', 'Meia esportiva', 19.90, 0.10, 100, false),
   115	            ('JAQ-001', 'Jaqueta corta-vento', 389.90, 0.80, 3, false),
   116	            ('MOC-001', 'Mochila urbana', 159.90, 0.90, 1, false),
   117	            ('BON-001', 'Boné aba reta', 59.90, 0.15, 0, false),
   118	            ('REL-001', 'Relógio digital', 129.90, 0.20, 8, true)
   119	            """;
   120	
   121	        try (Statement stmt = conn.createStatement()) {
   122	            stmt.execute(insertSql);
   123	        }
   124	    }
   125	
   126	    public static String toJson(Object obj) {
   127	        try {
   128	            return objectMapper.writeValueAsString(obj);
   129	        } catch (Exception e) {
   130	            throw new RuntimeException("Failed to serialize to JSON", e);
   131	        }
   132	    }
   133	
   134	    public static <T> T fromJson(String json, Class<T> clazz) {
   135	        try {
   136	            return objectMapper.readValue(json, clazz);
   137	        } catch (Exception e) {
   138	            throw new RuntimeException("Failed to deserialize from JSON", e);
   139	        }
   140	    }
   141	
   142	    public static CheckoutSummary getSummaryFromResultSet(ResultSet rs, String columnName) throws SQLException {
   143	        String json = rs.getString(columnName);
   144	        return fromJson(json, CheckoutSummary.class);
   145	    }
   146	
   147	    public static List<OrderItem> getItemsFromResultSet(ResultSet rs, String columnName) throws SQLException {
   148	        String json = rs.getString(columnName);
   149	        try {
   150	            return objectMapper.readValue(json,
   151	                objectMapper.getTypeFactory().constructCollectionType(List.class, OrderItem.class));
   152	        } catch (Exception e) {
   153	            throw new SQLException("Failed to parse items", e);
   154	        }
   155	    }
   156	
   157	    public static PGobject createJsonb(Object obj) throws SQLException {
   158	        PGobject jsonb = new PGobject();
   159	        jsonb.setType("jsonb");
   160	        jsonb.setValue(toJson(obj));
   161	        return jsonb;
   162	    }
   163	}
