     2	
     3	import com.fasterxml.jackson.databind.ObjectMapper;
     4	import com.fasterxml.jackson.databind.SerializationFeature;
     5	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
     6	import com.shop.config.Database;
     7	import com.shop.controller.*;
     8	import com.shop.repository.*;
     9	import com.shop.service.*;
    10	import io.javalin.Javalin;
    11	import io.javalin.json.JavalinJackson;
    12	
    13	public class Main {
    14	    public static void main(String[] args) {
    15	        String dbUrl = System.getenv().getOrDefault("DB_URL", "jdbc:postgresql://localhost:5432/shop");
    16	        String dbUser = System.getenv().getOrDefault("DB_USER", "postgres");
    17	        String dbPassword = System.getenv().getOrDefault("DB_PASSWORD", "postgres");
    18	        String translogUrl = System.getenv().getOrDefault("TRANSLOG_URL", "http://localhost:8081");
    19	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "8080"));
    20	
    21	        Database database = new Database(dbUrl, dbUser, dbPassword);
    22	        database.initialize();
    23	
    24	        ProductRepository productRepository = new ProductRepository(database);
    25	        CustomerRepository customerRepository = new CustomerRepository(database);
    26	        OrderRepository orderRepository = new OrderRepository(database);
    27	        NotificationRepository notificationRepository = new NotificationRepository(database);
    28	
    29	        ShippingService shippingService = new ShippingService(translogUrl);
    30	        CouponService couponService = new CouponService();
    31	        ClubService clubService = new ClubService();
    32	        PaymentService paymentService = new PaymentService();
    33	
    34	        CheckoutService checkoutService = new CheckoutService(
    35	                productRepository, orderRepository, shippingService,
    36	                couponService, clubService, paymentService);
    37	
    38	        OrderService orderService = new OrderService(
    39	                database, orderRepository, productRepository,
    40	                customerRepository, notificationRepository, checkoutService);
    41	
    42	        CheckoutController checkoutController = new CheckoutController(checkoutService);
    43	        OrderController orderController = new OrderController(orderService);
    44	        ProductController productController = new ProductController(productRepository);
    45	        CustomerController customerController = new CustomerController(customerRepository, notificationRepository);
    46	
    47	        ObjectMapper objectMapper = new ObjectMapper()
    48	                .registerModule(new JavaTimeModule())
    49	                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
    50	
    51	        Javalin app = Javalin.create(config -> {
    52	            config.jsonMapper(new JavalinJackson(objectMapper, true));
    53	        });
    54	
    55	        app.post("/checkout/summary", checkoutController::calculateSummary);
    56	
    57	        app.post("/orders", orderController::createOrder);
    58	        app.get("/orders/{id}", orderController::getOrder);
    59	        app.post("/orders/{id}/payment", orderController::processPayment);
    60	        app.post("/orders/{id}/shipment", orderController::shipOrder);
    61	        app.post("/orders/{id}/delivery", orderController::deliverOrder);
    62	        app.post("/orders/{id}/cancellation", orderController::cancelOrder);
    63	
    64	        app.get("/products/{sku}", productController::getProduct);
    65	
    66	        app.get("/customers/{cpf}", customerController::getCustomer);
    67	        app.get("/customers/{cpf}/notifications", customerController::getNotifications);
    68	        app.post("/notifications/{id}/read", customerController::markNotificationAsRead);
    69	
    70	        app.start(port);
    71	
    72	        System.out.println("Server started on port " + port);
    73	    }
    74	}
