  3	import com.shop.config.Database;
  4	import com.shop.model.Customer;
  5	
  6	import java.math.BigDecimal;
  7	import java.sql.*;
  8	
  9	public class CustomerRepository {
 10	    private final Database database;
 11	
 12	    public CustomerRepository(Database database) {
 13	        this.database = database;
 14	    }
 15	
 16	    public Customer findByCpf(String cpf) {
 17	        String sql = "SELECT * FROM customers WHERE cpf = ?";
 18	        try (Connection conn = database.getConnection();
 19	             PreparedStatement stmt = conn.prepareStatement(sql)) {
 20	            stmt.setString(1, cpf);
 21	            try (ResultSet rs = stmt.executeQuery()) {
 22	                if (rs.next()) {
 23	                    return mapCustomer(rs);
 24	                }
 25	                return null;
 26	            }
 27	        } catch (SQLException e) {
 28	            throw new RuntimeException("Failed to find customer", e);
 29	        }
 30	    }
 31	
 32	    public Customer findByCpfForUpdate(Connection conn, String cpf) throws SQLException {
 33	        String sql = "SELECT * FROM customers WHERE cpf = ? FOR UPDATE";
 34	        try (PreparedStatement stmt = conn.prepareStatement(sql)) {
 35	            stmt.setString(1, cpf);
 36	            try (ResultSet rs = stmt.executeQuery()) {
 37	                if (rs.next()) {
 38	                    return mapCustomer(rs);
 39	                }
 40	                return null;
 41	            }
 42	        }
 43	    }
 44	
 45	    public void create(Connection conn, String cpf, String email) throws SQLException {
 46	        String sql = "INSERT INTO customers (cpf, email, credit_balance) VALUES (?, ?, 0) ON CONFLICT (cpf) DO NOTHING";
 47	        try (PreparedStatement stmt = conn.prepareStatement(sql)) {
 48	            stmt.setString(1, cpf);
 49	            stmt.setString(2, email);
 50	            stmt.executeUpdate();
 51	        }
 52	    }
 53	
 54	    public void addCredit(Connection conn, String cpf, BigDecimal amount) throws SQLException {
 55	        String sql = "UPDATE customers SET credit_balance = credit_balance + ? WHERE cpf = ?";
 56	        try (PreparedStatement stmt = conn.prepareStatement(sql)) {
 57	            stmt.setBigDecimal(1, amount);
 58	            stmt.setString(2, cpf);
 59	            stmt.executeUpdate();
 60	        }
 61	    }
 62	
 63	    public void subtractCredit(Connection conn, String cpf, BigDecimal amount) throws SQLException {
 64	        String sql = "UPDATE customers SET credit_balance = credit_balance - ? WHERE cpf = ?";
 65	        try (PreparedStatement stmt = conn.prepareStatement(sql)) {
 66	            stmt.setBigDecimal(1, amount);
 67	            stmt.setString(2, cpf);
 68	            stmt.executeUpdate();
 69	        }
 70	    }
 71	
 72	    private Customer mapCustomer(ResultSet rs) throws SQLException {
 73	        Customer customer = new Customer();
 74	        customer.setCpf(rs.getString("cpf"));
 75	        customer.setEmail(rs.getString("email"));
 76	        customer.setCreditBalance(rs.getBigDecimal("credit_balance"));
 77	        return customer;
 78	    }
 79	}
 80	package com.shop.repository;
 81	
 82	import com.shop.config.Database;
 83	import com.shop.model.Notification;
 84	import com.shop.model.enums.NotificationStatus;
 85	import com.shop.model.enums.NotificationType;
 86	
 87	import java.sql.*;
 88	import java.util.ArrayList;
 89	import java.util.List;
 90	
 91	public class NotificationRepository {
 92	    private final Database database;
 93	
 94	    public NotificationRepository(Database database) {
 95	        this.database = database;
 96	    }
 97	
 98	    public Notification findById(Long id) {
 99	        String sql = "SELECT * FROM notifications WHERE id = ?";
100	        try (Connection conn = database.getConnection();
101	             PreparedStatement stmt = conn.prepareStatement(sql)) {
102	            stmt.setLong(1, id);
103	            try (ResultSet rs = stmt.executeQuery()) {
104	                if (rs.next()) {
105	                    return mapNotification(rs);
106	                }
107	                return null;
108	            }
109	        } catch (SQLException e) {
110	            throw new RuntimeException("Failed to find notification", e);
111	        }
112	    }
113	
114	    public List<Notification> findByCustomerCpf(String cpf) {
115	        String sql = "SELECT * FROM notifications WHERE customer_cpf = ? ORDER BY id ASC";
116	        List<Notification> notifications = new ArrayList<>();
117	        try (Connection conn = database.getConnection();
118	             PreparedStatement stmt = conn.prepareStatement(sql)) {
119	            stmt.setString(1, cpf);
120	            try (ResultSet rs = stmt.executeQuery()) {
121	                while (rs.next()) {
122	                    notifications.add(mapNotification(rs));
123	                }
124	            }
125	        } catch (SQLException e) {
126	            throw new RuntimeException("Failed to find notifications", e);
127	        }
128	        return notifications;
129	    }
130	
131	    public void create(Connection conn, NotificationType type, Long orderId, String customerCpf) throws SQLException {
132	        String sql = """
133	            INSERT INTO notifications (type, order_id, customer_cpf, status)
134	            VALUES (?, ?, ?, ?)
135	            """;
136	        try (PreparedStatement stmt = conn.prepareStatement(sql)) {
137	            stmt.setString(1, type.name());
138	            stmt.setLong(2, orderId);
139	            stmt.setString(3, customerCpf);
140	            stmt.setString(4, NotificationStatus.NEW.name());
141	            stmt.executeUpdate();
142	        }
143	    }
144	
145	    public void markAsRead(Long id) {
146	        String sql = "UPDATE notifications SET status = ? WHERE id = ?";
147	        try (Connection conn = database.getConnection();
148	             PreparedStatement stmt = conn.prepareStatement(sql)) {
149	            stmt.setString(1, NotificationStatus.READ.name());
150	            stmt.setLong(2, id);
151	            stmt.executeUpdate();
152	        } catch (SQLException e) {
153	            throw new RuntimeException("Failed to mark notification as read", e);
154	        }
155	    }
156	
157	    private Notification mapNotification(ResultSet rs) throws SQLException {
158	        Notification notification = new Notification();
159	        notification.setId(rs.getLong("id"));
160	        notification.setType(NotificationType.valueOf(rs.getString("type")));
161	        notification.setOrderId(rs.getLong("order_id"));
162	        notification.setCustomerCpf(rs.getString("customer_cpf"));
163	        notification.setStatus(NotificationStatus.valueOf(rs.getString("status")));
164	        return notification;
165	    }
166	}
