  1	package com.shop.service;
  2	
  3	import com.shop.config.Database;
  4	import com.shop.dto.CheckoutRequest;
  5	import com.shop.dto.CheckoutSummary;
  6	import com.shop.exception.BusinessException;
  7	import com.shop.model.Order;
  8	import com.shop.model.OrderItem;
  9	import com.shop.model.enums.NotificationType;
 10	import com.shop.model.enums.OrderStatus;
 11	import com.shop.repository.CustomerRepository;
 12	import com.shop.repository.NotificationRepository;
 13	import com.shop.repository.OrderRepository;
 14	import com.shop.repository.ProductRepository;
 15	
 16	import java.sql.Connection;
 17	import java.sql.SQLException;
 18	import java.time.Duration;
 19	import java.time.Instant;
 20	import java.util.HashMap;
 21	import java.util.Map;
 22	
 23	public class OrderService {
 24	    private final Database database;
 25	    private final OrderRepository orderRepository;
 26	    private final ProductRepository productRepository;
 27	    private final CustomerRepository customerRepository;
 28	    private final NotificationRepository notificationRepository;
 29	    private final CheckoutService checkoutService;
 30	
 31	    private final Map<String, PaymentResult> paymentCache = new HashMap<>();
 32	
 33	    private static class PaymentResult {
 34	        boolean success;
 35	        String errorCode;
 36	        Order order;
 37	
 38	        PaymentResult(boolean success, String errorCode, Order order) {
 39	            this.success = success;
 40	            this.errorCode = errorCode;
 41	            this.order = order;
 42	        }
 43	    }
 44	
 45	    public OrderService(Database database, OrderRepository orderRepository,
 46	                       ProductRepository productRepository, CustomerRepository customerRepository,
 47	                       NotificationRepository notificationRepository, CheckoutService checkoutService) {
 48	        this.database = database;
 49	        this.orderRepository = orderRepository;
 50	        this.productRepository = productRepository;
 51	        this.customerRepository = customerRepository;
 52	        this.notificationRepository = notificationRepository;
 53	        this.checkoutService = checkoutService;
 54	    }
 55	
 56	    public Order createOrder(CheckoutRequest request) {
 57	        try (Connection conn = database.getConnection()) {
 58	            conn.setAutoCommit(false);
 59	            try {
 60	                CheckoutSummary summary = checkoutService.calculateSummary(request, conn);
 61	
 62	                customerRepository.create(conn, request.getCustomer().getCpf(), request.getCustomer().getEmail());
 63	
 64	                Long orderId = orderRepository.create(conn, request.getCustomer().getCpf(), summary, request.getItems());
 65	
 66	                conn.commit();
 67	
 68	                return orderRepository.findById(orderId);
 69	            } catch (BusinessException e) {
 70	                conn.rollback();
 71	                throw e;
 72	            } catch (Exception e) {
 73	                conn.rollback();
 74	                throw new RuntimeException("Failed to create order", e);
 75	            }
 76	        } catch (SQLException e) {
 77	            throw new RuntimeException("Database connection failed", e);
 78	        }
 79	    }
 80	
 81	    public Order processPayment(Long orderId, String transactionId, Instant paidAt) {
 82	        String cacheKey = orderId + ":" + transactionId;
 83	
 84	        synchronized (paymentCache) {
 85	            if (paymentCache.containsKey(cacheKey)) {
 86	                PaymentResult cached = paymentCache.get(cacheKey);
 87	                if (!cached.success) {
 88	                    throw new BusinessException(cached.errorCode, 409);
 89	                }
 90	                return cached.order;
 91	            }
 92	        }
 93	
 94	        try (Connection conn = database.getConnection()) {
 95	            conn.setAutoCommit(false);
 96	            try {
 97	                Order order = orderRepository.findByIdForUpdate(conn, orderId);
 98	                if (order == null) {
 99	                    throw new BusinessException("ORDER_NOT_FOUND", 404);
100	                }
101	
102	                if (order.getStatus() != OrderStatus.AWAITING_PAYMENT) {
103	                    throw new BusinessException("OPERATION_NOT_ALLOWED", 409);
104	                }
105	
106	                Duration timeSinceCreation = Duration.between(order.getCreatedAt(), paidAt);
107	                if (timeSinceCreation.toHours() > 48) {
108	                    orderRepository.updateStatus(conn, orderId, OrderStatus.CANCELLED);
109	                    orderRepository.updatePaymentTransaction(conn, orderId, transactionId);
110	                    notificationRepository.create(conn, NotificationType.ORDER_CANCELLED, orderId, order.getCustomerCpf());
111	                    conn.commit();
112	
113	                    Order cancelledOrder = orderRepository.findById(orderId);
114	                    synchronized (paymentCache) {
115	                        paymentCache.put(cacheKey, new PaymentResult(false, "ORDER_EXPIRED", cancelledOrder));
116	                    }
117	                    throw new BusinessException("ORDER_EXPIRED", 409);
118	                }
119	
120	                try {
121	                    for (OrderItem item : order.getItems()) {
122	                        productRepository.decrementStock(conn, item.getSku(), item.getQuantity());
123	                    }
124	                } catch (SQLException e) {
125	                    orderRepository.updateStatus(conn, orderId, OrderStatus.CANCELLED);
126	                    orderRepository.updatePaymentTransaction(conn, orderId, transactionId);
127	                    notificationRepository.create(conn, NotificationType.ORDER_CANCELLED, orderId, order.getCustomerCpf());
